<script setup>
import {ref,onMounted,watch} from 'vue'
import {paymentStates} from '../../../shared/payments.js'
import {orderStatuses,orderTransitions,deliveryMethods} from '../../../shared/commerce.js'
const props=defineProps({mode:String,apiWrite:Function})
const emit=defineEmits(['changed'])
const rows=ref([]),total=ref(0),page=ref(1),search=ref(''),status=ref(''),loading=ref(false),busy=ref(false),error=ref(''),order=ref(null),customer=ref(null),targetStatus=ref(''),note=ref('')
const jobs=ref([]),ledger=ref(null),tracking=ref({code:'',url:''}),ack=ref(false)
async function operations(id){[jobs.value,ledger.value]=await Promise.all([props.apiWrite('/api/admin/orders/'+id+'/notifications','GET'),props.apiWrite('/api/admin/orders/'+id+'/payments','GET')]);tracking.value={code:order.value.tracking_code||'',url:order.value.tracking_url||''};ack.value=false}
async function saveShipping(){busy.value=true;error.value='';try{const id=order.value.id;await props.apiWrite('/api/admin/orders/'+id+'/shipping','PUT',{revision:order.value.revision,tracking_code:tracking.value.code,tracking_url:tracking.value.url});order.value=await props.apiWrite('/api/admin/orders/'+id,'GET');await operations(id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function retry(job){busy.value=true;error.value='';try{await props.apiWrite('/api/admin/orders/'+order.value.id+'/notifications/'+job.id+'/retry','POST',{acknowledge:ack.value});await operations(order.value.id)}catch(e){error.value=e.message}finally{busy.value=false}}
const notificationStates={queued:'В очереди',sending:'Отправляется',sent:'Принято сервисом',partial:'Принято частично',failed:'Ошибка',uncertain:'Результат неизвестен'}
const paymentReference=ref(''),paymentTarget=ref('paid')
async function savePayment(){if(busy.value)return;busy.value=true;error.value='';try{await props.apiWrite('/api/admin/orders/'+order.value.id+'/payment','PUT',{revision:order.value.revision,state:paymentTarget.value,reference:paymentReference.value});order.value=await props.apiWrite('/api/admin/orders/'+order.value.id,'GET');targetStatus.value=order.value.status;paymentTarget.value=order.value.payment_state==='paid'?'refunded':'paid';paymentReference.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
const money=cents=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB'}).format(cents/100)
const date=value=>new Date(value).toLocaleString('ru-RU')
let generation=0
async function load(reset=false){if(reset)page.value=1;const token=++generation;loading.value=true;error.value='';try{const data=await props.apiWrite('/api/admin/'+props.mode+'?'+new URLSearchParams({page:String(page.value),search:search.value,...(props.mode==='orders'?{status:status.value}:{})}),'GET');if(token!==generation)return;rows.value=data.rows;total.value=data.total}catch(e){if(token===generation)error.value=e.message}finally{if(token===generation)loading.value=false}}
async function openOrder(id){if(busy.value)return;busy.value=true;error.value='';try{order.value=await props.apiWrite('/api/admin/orders/'+id,'GET');targetStatus.value=order.value.status;note.value=order.value.admin_note;await operations(id);paymentReference.value='';paymentTarget.value=order.value.payment_state==='paid'?'refunded':'paid'}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveOrder(){if(busy.value)return;busy.value=true;error.value='';try{order.value=await props.apiWrite('/api/admin/orders/'+order.value.id,'PUT',{revision:order.value.revision,status:targetStatus.value,admin_note:note.value});targetStatus.value=order.value.status;await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function openCustomer(id,p=1){if(busy.value)return;busy.value=true;error.value='';try{customer.value=await props.apiWrite('/api/admin/customers/'+id+'?page='+p,'GET')}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveCustomer(){if(busy.value)return;busy.value=true;error.value='';try{await props.apiWrite('/api/admin/customers/'+customer.value.id,'PUT',{revision:customer.value.revision,name:customer.value.name,phone:customer.value.phone,email:customer.value.email,note:customer.value.note});customer.value=await props.apiWrite('/api/admin/customers/'+customer.value.id,'GET');await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function changePage(delta){page.value+=delta;await load()}
watch(()=>props.mode,()=>{search.value='';status.value='';order.value=null;customer.value=null;load(true)})
onMounted(()=>load())
</script>
<template>
<div class="commerce-workspace">
 <div class="page-title"><div><span class="eyebrow">МАГАЗИН</span><h1>{{mode==='orders'?'Заказы':'Покупатели'}}</h1><p>{{mode==='orders'?'Оформления с сайта, состав и обработка заказов.':'Контактные карточки автоматически создаются при оформлении заказа.'}}</p></div><button class="row-btn" :disabled="loading||busy" @click="load()">Обновить</button></div>
 <p v-if="error" class="alert" role="alert">{{error}}</p>
 <div class="panel"><form class="panel-heading commerce-filters" @submit.prevent="load(true)"><h2>{{mode==='orders'?'Заказов':'Покупателей'}}: {{total}}</h2><input v-model="search" class="search-input" maxlength="150" :placeholder="mode==='orders'?'Номер, имя, телефон или email':'Имя, телефон или email'" aria-label="Поиск"><select v-if="mode==='orders'" v-model="status" aria-label="Статус заказа"><option value="">Все статусы</option><option v-for="(label,key) in orderStatuses" :key="key" :value="key">{{label}}</option></select><button class="row-btn" :disabled="loading">Найти</button></form>
 <p v-if="loading" class="empty" role="status">Загрузка…</p><div v-else class="table-scroll"><table v-if="mode==='orders'"><thead><tr><th>Заказ</th><th>Покупатель</th><th>Статус</th><th>Оплата</th><th>Итого с доставкой</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.number}}</strong><small>{{date(row.created_at)}}</small></td><td>{{row.customer_name}}<small>{{row.phone}}</small></td><td><span class="order-status" :class="row.status">{{orderStatuses[row.status]}}</span></td><td>{{paymentStates[row.payment_state]}}</td><td>{{money(row.total_cents)}}</td><td><button class="row-btn" :disabled="busy" @click="openOrder(row.id)">Открыть заказ</button></td></tr></tbody></table>
 <table v-else><thead><tr><th>Покупатель</th><th>Контакты</th><th>Заказов</th><th>Сумма без отмен</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.name}}</strong><small>С {{date(row.created_at)}}</small></td><td>{{row.phone}}<small>{{row.email||'—'}}</small></td><td>{{row.orders_count}}</td><td>{{money(row.total_cents)}}</td><td><button class="row-btn" :disabled="busy" @click="openCustomer(row.id)">Открыть покупателя</button></td></tr></tbody></table>
 <p v-if="!rows.length" class="empty">{{search||status?'Ничего не найдено.':mode==='orders'?'Заказов пока нет. Первый появится после оформления покупки через корзину сайта.':'Покупателей пока нет. Карточка появится после первого заказа.'}}</p></div>
 <div class="commerce-pagination"><button class="row-btn" :disabled="loading||page<=1" @click="changePage(-1)">← Назад</button><span>{{page}} / {{Math.max(1,Math.ceil(total/25))}}</span><button class="row-btn" :disabled="loading||page*25>=total" @click="changePage(1)">Далее →</button></div></div>
 <div v-if="customer" class="modal-backdrop"><div class="modal commerce-modal" role="dialog" aria-modal="true" aria-label="Карточка покупателя"><div class="modal-heading"><h2>{{customer.name}}</h2><button aria-label="Закрыть покупателя" :disabled="busy" @click="customer=null">×</button></div><p>Заказов: {{customer.orders_count}} · Сумма без отмен: {{money(customer.total_cents)}}</p><p class="commerce-muted">Карточка контакта, без личного кабинета и проверки владельца телефона. Заказы объединяются по номеру телефона. Изменения карточки не меняют контакты в ранее оформленных заказах.</p><form @submit.prevent="saveCustomer"><fieldset :disabled="busy"><label>Имя<input v-model="customer.name" maxlength="150" required></label><label>Телефон<input v-model="customer.phone" type="tel" maxlength="40" required></label><label>Email<input v-model="customer.email" type="email" maxlength="254"></label><label>Внутренняя заметка<textarea v-model="customer.note" maxlength="5000" rows="3"></textarea></label><button class="primary-btn">Сохранить карточку</button></fieldset></form><p v-if="error" class="alert" role="alert">{{error}}</p><h3>История заказов</h3><div class="table-scroll"><table><thead><tr><th>Заказ</th><th>Дата</th><th>Статус</th><th>Сумма</th></tr></thead><tbody><tr v-for="item in customer.orders" :key="item.id"><td><button class="row-btn" :disabled="busy" @click="openOrder(item.id)">{{item.number}}</button></td><td>{{date(item.created_at)}}</td><td>{{orderStatuses[item.status]}}</td><td>{{money(item.total_cents)}}</td></tr></tbody></table></div><div class="commerce-pagination"><button class="row-btn" :disabled="busy||customer.page<=1" @click="openCustomer(customer.id,customer.page-1)">←</button><span>Страница {{customer.page}}</span><button class="row-btn" :disabled="busy||customer.page*25>=customer.orders_count" @click="openCustomer(customer.id,customer.page+1)">→</button></div></div></div>
 <div v-if="order" class="modal-backdrop commerce-order-overlay"><div class="modal commerce-modal" role="dialog" aria-modal="true" aria-label="Карточка заказа"><div class="modal-heading"><h2>Заказ {{order.number}}</h2><button aria-label="Закрыть заказ" :disabled="busy" @click="order=null">×</button></div><p>{{date(order.created_at)}} · {{orderStatuses[order.status]}}</p><div class="commerce-contact"><strong>{{order.customer_name}}</strong><span>{{order.phone}}</span><span>{{order.email||'Email не указан'}}</span><button class="row-btn" :disabled="busy" @click="openCustomer(order.customer_id);order=null">Карточка покупателя</button></div><p><strong>{{order.delivery_snapshot?.title||deliveryMethods[order.delivery_method]}}</strong></p><p class="commerce-pre">{{order.address}}</p><p v-if="order.comment" class="commerce-pre">Комментарий: {{order.comment}}</p><div class="table-scroll"><table><thead><tr><th>Товар</th><th>Цена</th><th>Кол-во</th><th>Сумма</th></tr></thead><tbody><tr v-for="item in order.items" :key="item.id"><td><strong>{{item.name}}</strong><small>{{item.variant_name}}</small><small>{{item.sku}}</small></td><td>{{money(item.unit_cents)}}</td><td>{{item.quantity}}</td><td>{{money(item.unit_cents*item.quantity)}}</td></tr></tbody></table></div><p class="commerce-total">Товары: {{money(order.total_cents-Number(order.delivery_cents||0))}} · Доставка: {{money(Number(order.delivery_cents||0))}} · Итого: {{money(order.total_cents)}}</p><p class="commerce-muted">Остатки уменьшены при оформлении; при отмене существующие товары и варианты возвращаются на склад. Предупреждения о переименованных или удалённых вариантах указаны в истории.</p><p v-if="order.payment_review" class="alert" role="alert">Требуется проверка оплаты: деньги поступили после отмены или повторно. Заказ не возобновлён. Проверьте операции и при необходимости выполните возврат в кабинете сервиса.</p><section class="commerce-payment"><h3>Оплата: {{paymentStates[order.payment_state]}}</h3><p class="commerce-muted">Отметка не списывает и не возвращает деньги. Сначала проверьте полную сумму в кабинете сервиса. Для возврата сначала выполните операцию там. Укажите номер операции или основание: запись останется в истории заказа.</p><form v-if="order.payment_state!=='refunded'&&(order.status!=='cancelled'||order.payment_state==='paid')" @submit.prevent="savePayment"><fieldset :disabled="busy"><label>Подтверждённая операция<select v-model="paymentTarget"><option v-if="order.payment_state==='unpaid'" value="paid">Получена полная оплата</option><option v-if="order.payment_state==='paid'" value="refunded">Выполнен полный возврат</option></select></label><label>Номер операции / основание<input v-model="paymentReference" maxlength="500" required></label><button class="row-btn" :disabled="!paymentReference.trim()">Записать подтверждение</button></fieldset></form><p v-for="a in ledger?.attempts||[]" :key="a.id" class="commerce-muted">Счёт {{a.provider}} · {{a.test?'тестовый':'боевой'}} · {{a.provider_id||'Создание не подтверждено'}} · {{money(Number(a.amount_cents))}}</p><p v-for="p in ledger?.payments||[]" :key="p.transaction_id" class="commerce-muted">Проверенная оплата: {{p.provider}} / {{p.transaction_id}} · {{money(Number(p.amount_cents))}}</p></section><section class="commerce-payment"><h3>Отправление</h3><form @submit.prevent="saveShipping"><fieldset :disabled="busy"><label>Трек-номер<input v-model="tracking.code" maxlength="120"></label><label>HTTPS-ссылка отслеживания<input v-model="tracking.url" type="url" maxlength="2000" placeholder="https://…"></label><button class="row-btn">Сохранить отправление</button></fieldset></form></section><section class="commerce-payment"><h3>Уведомления</h3><p v-if="!jobs.length" class="commerce-muted">Отправок пока нет. Новые события попадают в очередь в течение нескольких секунд при включённых каналах.</p><label v-if="jobs.some(j=>['failed','partial','uncertain'].includes(j.state))"><input v-model="ack" type="checkbox"> Проверил доставку: разрешаю повтор, возможен дубль</label><p v-for="job in jobs" :key="job.id" class="commerce-muted">{{job.audience==='customer'?'Покупатель':'Магазин'}} · {{job.channel}} · {{notificationStates[job.state]||job.state}} · попыток: {{job.attempts}} {{job.error_code}} <button v-if="['failed','partial','uncertain'].includes(job.state)" type="button" class="row-btn" :disabled="busy||!ack" @click="retry(job)">Повторить отправку</button></p></section><form @submit.prevent="saveOrder"><fieldset :disabled="busy"><label>Статус<select v-model="targetStatus" aria-label="Статус"><option :value="order.status">{{orderStatuses[order.status]}}</option><option v-for="next in orderTransitions[order.status]" :key="next" :value="next">{{orderStatuses[next]}}</option></select></label><label>Внутренняя заметка<textarea v-model="note" maxlength="5000" rows="3"></textarea></label><p v-if="error" class="alert" role="alert">{{error}}</p><div class="modal-actions"><button type="button" class="cancel-btn" @click="openOrder(order.id)">Обновить карточку</button><button class="primary-btn">{{busy?'Сохранение…':'Сохранить заказ'}}</button></div></fieldset></form><h3>История обработки</h3><ol class="commerce-history"><li v-for="event in order.history" :key="event.id"><strong>{{orderStatuses[event.status]}}</strong><small>{{date(event.created_at)}}</small><p>{{event.message}}</p></li></ol></div></div>
</div>
</template>
<style scoped>
.commerce-payment{padding:18px;margin:20px 0;background:#f2f7f4;border-radius:8px}.commerce-payment input{padding:10px;border:1px solid #d1dfd7;border-radius:7px}.commerce-filters{gap:12px;flex-wrap:wrap}.commerce-filters select{padding:10px;border:1px solid #dbe5e2;border-radius:7px;background:#fff;max-width:100%}.commerce-workspace small{display:block;font-size:11px;color:#687f77;margin-top:6px;overflow-wrap:anywhere}.commerce-pagination{display:flex;align-items:center;justify-content:center;gap:16px;padding:20px;font-size:12px}.commerce-modal{width:min(900px,100%)}.commerce-modal fieldset{display:grid;gap:15px;border:0;margin:0;padding:0;min-width:0}.commerce-order-overlay{z-index:52}.commerce-contact{display:grid;gap:10px;padding:18px;background:#f3f7f5;border-radius:8px}.commerce-contact button{justify-self:start;margin:0}.commerce-pre{white-space:pre-wrap;overflow-wrap:anywhere}.commerce-total{text-align:right;font-size:20px;font-weight:800}.commerce-muted{font-size:12px;line-height:1.7;color:#687f77}.commerce-history{padding-left:20px}.commerce-history li{padding:10px 0;border-bottom:1px solid #e4ebe6}.commerce-history p{font-size:12px;line-height:1.7}.order-status{font-size:11px;border-radius:20px;padding:7px 11px;background:#e9f0ec;white-space:nowrap}.order-status.new{background:#fff0d1;color:#8a5b0a}.order-status.completed{background:#e0f4e6;color:#28623e}.order-status.cancelled{background:#fae5e5;color:#973c3c}.commerce-workspace td{overflow-wrap:anywhere}.commerce-workspace button:disabled{opacity:.5;cursor:wait}
</style>
